window.SevenOrbitAssets=(()=>{
  const sources={"tiktok": "data:image/svg+xml;base64,", "jd": "data:image/x-icon;base64,", "xiaohongshu": "data:image/svg+xml;base64,", "bilibili": "data:image/svg+xml;base64,", "taobao": "data:image/svg+xml;base64,", "x": "data:image/svg+xml;base64,"};
  const images=new Map();
  const ready=Promise.all(Object.entries(sources).map(([key,uri])=>new Promise(resolve=>{const image=new Image();image.onload=()=>{images.set(key,image);resolve();};image.onerror=()=>resolve();image.src=uri;})));
  function draw(ctx,app,x,y,size){ctx.save();ctx.fillStyle=app.color;ctx.beginPath();ctx.roundRect(x,y,size,size,size*.245);ctx.fill();ctx.clip();const image=images.get(app.asset);if(image){const pad=app.asset==='jd'||app.asset==='pinduoduo'?0:size*.19;ctx.drawImage(image,x+pad,y+pad,size-pad*2,size-pad*2);}else{ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle='#ffffff';ctx.font=`500 ${size*(app.symbol.length>2?.34:.58)}px system-ui`;ctx.fillText(app.symbol,x+size/2,y+size*.52,size*.82);}ctx.restore();}
  return {ready,draw};
})();
